parameters.jsCode:
// Build the prompt sent to the LLM: it needs the job description plus the
// user's stated preferences / base resume so it can judge fit and write a summary.
const d = $json;
const prefs = d.preferences || {};

const systemPrompt = `You are an assistant that screens job postings for a job seeker.
You will be given the seeker's preferences/resume and a single job posting.
Respond with ONLY a raw JSON object (no markdown fences, no extra text) with this exact shape:
{
  "is_good_match": boolean,
  "match_score": number, // 0-100
  "summary": string, // 2-4 sentence summary of the role
  "key_requirements": string[], // top requirements extracted from the posting
  "reasoning": string // short explanation of why it is or isn't a good match
}`;

const userPrompt = `SEEKER PREFERENCES / RESUME:
Keywords: ${prefs.keywords || ''}
Desired locations: ${(prefs.locations || []).join(', ')}
Desired work type: ${(prefs.workType || []).join(', ')}
Desired employment type: ${(prefs.employmentType || []).join(', ')}
Minimum salary: ${prefs.minSalary || 'n/a'}
Excluded companies: ${(prefs.excludedCompanies || []).join(', ') || 'none'}
Match threshold (score needed to count as good match): ${prefs.matchThreshold || 70}

Base resume / background:
${prefs.baseResumeText || '(not provided)'}

---
JOB POSTING
Title: ${d.title}
Company: ${d.company}
URL: ${d.url}
Salary info (as listed, may be empty): ${d.salaryInfo || 'n/a'}
Experience level (as listed): ${d.experienceLevel || 'n/a'}
Sector: ${d.sector || 'n/a'}
Company info: ${d.companyInfo || 'n/a'}

Automatic resume-keyword pre-score from the scraper (0-100, informational only - use your own judgment on the full description, don't just defer to this number): ${d.resumeMatchScore ?? 'n/a'}
Keywords already matched: ${d.matchedKeywords || 'none'}
Keywords not found: ${d.unmatchedKeywords || 'none'}

Description:
${d.description}`;

return [
  {
    json: {
      ...d,
      systemPrompt,
      userPrompt
    }
  }
];

parameters.jsonBody:
={{ JSON.stringify({
  model: "meta-llama/llama-3.3-70b-instruct:free",
  messages: [
    { role: "system", content: $json.systemPrompt },
    { role: "user", content: $json.userPrompt }
  ],
  temperature: 0.2
}) }}

parameters.jsCode:
// Parse the LLM's JSON reply defensively (strip markdown fences if present).
const raw = $json.choices?.[0]?.message?.content || '{}';
const cleaned = raw.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    is_good_match: false,
    match_score: 0,
    summary: 'Could not parse LLM response.',
    key_requirements: [],
    reasoning: `Parse error: ${e.message}. Raw: ${raw.slice(0, 300)}`
  };
}

const job = $('Build LLM Prompt').first().json;

return [
  {
    json: {
      ...job,
      is_good_match: !!parsed.is_good_match,
      match_score: parsed.match_score || 0,
      summary: parsed.summary || '',
      key_requirements: (parsed.key_requirements || []).join('; '),
      reasoning: parsed.reasoning || ''
    }
  }
];

const cvResponse = $json;
const job = $('Parse LLM Response').first().json;

return [
  {
    json: {
      ...job,
      cv_text: cvResponse.cv_text || cvResponse.text || JSON.stringify(cvResponse)
    }
  }
];
